package toposort

import "testing"

func TestSimpleDAG(t *testing.T) {
	order, ok := TopoSort(4, [][2]int{{0, 1}, {0, 2}, {1, 3}, {2, 3}})
	if !ok {
		t.Fatal("expected no cycle")
	}
	pos := make([]int, 4)
	for i, v := range order {
		pos[v] = i
	}
	if pos[0] >= pos[1] || pos[0] >= pos[2] || pos[1] >= pos[3] || pos[2] >= pos[3] {
		t.Errorf("invalid topological order: %v", order)
	}
}

func TestCycle(t *testing.T) {
	_, ok := TopoSort(3, [][2]int{{0, 1}, {1, 2}, {2, 0}})
	if ok {
		t.Fatal("expected cycle detection to return false")
	}
}

func TestEmpty(t *testing.T) {
	order, ok := TopoSort(0, nil)
	if !ok {
		t.Fatal("no cycle in empty graph")
	}
	if len(order) != 0 {
		t.Errorf("expected empty order, got %v", order)
	}
}

func TestNoEdges(t *testing.T) {
	order, ok := TopoSort(3, nil)
	if !ok {
		t.Fatal("no cycle in edgeless graph")
	}
	if len(order) != 3 {
		t.Errorf("want 3 nodes, got %v", order)
	}
}

func TestLinearChain(t *testing.T) {
	order, ok := TopoSort(5, [][2]int{{0, 1}, {1, 2}, {2, 3}, {3, 4}})
	if !ok {
		t.Fatal("no cycle in linear chain")
	}
	if order[0] != 0 || order[4] != 4 {
		t.Errorf("expected 0..4 in order, got %v", order)
	}
}

